#!/bin/sh
# Runs the repository audit (tools/design/audit.js) on every screen and state, six at a time. Usage: sh tools/audit-all.sh [lang] [width] [height]
# Prints one line per page: overflow px, contrast failures, small targets; then the detail of any failure.
L=${1:-en}; W=${2:-390}; H=${3:-844}
cd "$(dirname "$0")/../../../.." || exit 1
one() { p="$1"; case "$p" in *\?*) u="$p&lang=$L";; *) u="$p?lang=$L";; esac
  AUDIT_ACCENT="#FFD400" node tools/design/audit.js "http://localhost:8856/$u" $W $H --mobile 2>&1 | awk -v u="$u" '/^overflow/{o=$3; if ($0 ~ /pageerrors/) o=o" PAGEERROR"} /^CONTRAST/{c=$NF; f=1; next} /^TARGETS/{t=$NF; f=1; next} /^(MONO|ACCENT)/{f=0} f&&/^  /{d=d"\n   "$0} END{print u": overflow "o", contrast "c", targets "t d}'; }
export -f one 2>/dev/null; export L W H
printf '%s\n' "index.html" "login.html" "login.html?state=code" "login.html?state=wrong" "login.html?state=bad" "first-run.html" "first-run.html?step=2" "first-run.html?step=3" "first-run.html?state=codeok" "first-run.html?state=codebad" "home.html" "home.html?state=partial" "home.html?state=hold" "home.html?state=empty" "home.html?state=loading" "home.html?state=error" "home.html?state=offline" "home-list.html" "home-list.html?state=partial" "done.html" "done.html?state=saving" "results.html" "results.html?state=empty" "results.html?state=loading" "ranking.html" "ranking.html?state=lastweek" "ranking.html?state=norank" "ranking.html?state=hold" "staking.html" "staking.html?state=review" "staking.html?state=errmin" "staking.html?state=errbal" "staking.html?state=hold" "stakes.html" "stakes.html?state=empty" "stakes.html?state=hold" "wallet.html" "wallet.html?state=deposit" "wallet.html?state=withdraw" "wallet.html?state=hold" "wallet.html?state=offline" "wallet.html?state=rpc" "convert.html" "convert.html?state=short" "convert.html?state=wait" "convert.html?state=ok" "profile.html" "profile.html?state=logout" "profile.html?state=hold" "invite.html" "invite.html?state=empty" "invite.html?state=hold" "hold.html" | xargs -P 6 -I{} bash -c 'one "{}"' | sort
